{"path": "src/debounce.js", "content": "// debounce(fn, ms): returns a function that delays calling fn until ms have passed without
// another call; fn gets the arguments of the last call. The returned function has .cancel()
// (drop the pending call) and .flush() (run the pending call now, if any).
export function debounce(fn, ms) {
  let timer;
  let pendingArgs = null;
  let pendingThis;

  const run = () => {
    const args = pendingArgs;
    const ctx = pendingThis;
    timer = undefined;
    pendingArgs = null;
    pendingThis = undefined;
    fn.apply(ctx, args);
  };

  function debounced(...args) {
    clearTimeout(timer);
    pendingArgs = args;
    pendingThis = this;
    timer = setTimeout(run, ms);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = undefined;
    pendingArgs = null;
    pendingThis = undefined;
  };

  debounced.flush = () => {
    if (pendingArgs === null) return;
    clearTimeout(timer);
    run();
  };

  return debounced;
}
"}

{"path": "test/debounce.test.js", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { debounce } from '../src/debounce.js';

test('exists', () => assert.equal(typeof debounce(() => {}, 10), 'function'));

test('calls once with the last arguments after the delay', async () => {
  const calls = [];
  const d = debounce((...a) => calls.push(a), 20);
  d(1); d(2); d(3);
  assert.equal(calls.length, 0);
  await new Promise((r) => setTimeout(r, 40));
  assert.deepEqual(calls, [[3]]);
});

test('cancel drops the pending call', async () => {
  let n = 0;
  const d = debounce(() => n++, 10);
  d(); d.cancel();
  await new Promise((r) => setTimeout(r, 30));
  assert.equal(n, 0);
});

test('flush runs the pending call now, once, and is a no-op otherwise', async () => {
  const calls = [];
  const d = debounce((x) => calls.push(x), 10);
  d.flush();
  assert.deepEqual(calls, []);
  d('a'); d('b'); d.flush();
  assert.deepEqual(calls, ['b']);
  await new Promise((r) => setTimeout(r, 30));
  d.flush();
  assert.deepEqual(calls, ['b']);
});
"}
